use horizon_client::mod_api::*;

#[derive(Default)]
pub struct ChunkCourier {
    ticks: std::sync::atomic::AtomicI32,
}

impl horizon_client::mod_api::Hooks for ChunkCourier {
    /// Ported from ChunkCourier::onPlayerTick: counts player ticks and sends the
    /// ticking player a status message every 20 ticks.
    fn player_tick(&self, host: &mut dyn Host, _event: &mut PlayerTickEvent) {
        if host.acting_player().is_none() {
            return;
        }
        let ticks = self
            .ticks
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed)
            .wrapping_add(1);
        if ticks % 20 == 0 {
            host.feedback(Text::literal(&format!(
                "chunkcourier: parcels ticked {}",
                ticks
            )));
        }
    }
}
